function bindPage(){ if(page==='purchases')bindPurchases(); if(page==='purchase-edit')bindPurchaseEditPage(); if(page==='billing') bindBilling(); if(page==='products'){ document.querySelector('#new-product')?.addEventListener('click',()=>productDialog()); document.querySelector('#empty-add-product')?.addEventListener('click',()=>productDialog()); document.querySelector('#inventory-search')?.addEventListener('input',e=>{const q=e.target.value.toLowerCase();document.querySelector('#products-table').innerHTML=products.filter(p=>String(p.name||'').toLowerCase().includes(q)).map(productRow).join('')||'<tr><td colspan="8" class="cart-empty">No matching products.</td></tr>'}); } if(page==='customers'){document.querySelector('#new-customer')?.addEventListener('click',()=>customerDialog());document.querySelector('#customers-table')?.addEventListener('click',e=>{const b=e.target.closest('[data-payment]');if(b)paymentDialog(b.dataset.payment)});document.querySelector('#customer-search')?.addEventListener('input',e=>{const q=e.target.value.toLowerCase();document.querySelector('#customers-table').innerHTML=customers.filter(c=>`${c.name} ${c.phone}`.toLowerCase().includes(q)).map(customerRow).join('')||'<tr><td colspan="5" class="cart-empty">No matching customers.</td></tr>'});} if(page==='transactions')document.querySelector('#transaction-search')?.addEventListener('input',e=>{const q=e.target.value.toLowerCase();document.querySelector('#transactions-table').innerHTML=transactions.filter(t=>`${t.reference} ${customers.find(c=>c.id===t.customer_id)?.name||t.customer_name||''}`.toLowerCase().includes(q)).map(t=>`<tr><td class="mono"><b>${escapeHtml(t.reference||'—')}</b></td><td>${escapeHtml(customers.find(c=>c.id===t.customer_id)?.name||t.customer_name||'Walk-in customer')}</td><td><span class="pill green">${escapeHtml(t.type)}${t.sale_type?` · ${escapeHtml(t.sale_type)}`:''}</span></td><td class="amount">${currency(t.total)}</td><td>${new Date(t.created_at).toLocaleString('en-IN')}</td></tr>`).join('')}); if(page==='settings')bindAiSettings(); }
let cart=[];
function billDiscount(){return Number(document.querySelector('#customer-discount')?.value||0)}
function lineDiscount(row){return Number(row.discountRate??billDiscount())}
function discountedInclusive(p,discount=billDiscount()){return money(Number(p.mrp||0)*(1-discount/100))}
function wholesaleUnit(p,discount=billDiscount()){return money(discountedInclusive(p,discount)/1.05)}
function wholesaleGst(p,discount=billDiscount()){return money(discountedInclusive(p,discount)-wholesaleUnit(p,discount))}
function purchaseDate(p){if(!p.last_purchase_date)return 'Purchase date unavailable';return new Date(`${p.last_purchase_date}T00:00:00`).toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'})}
