function searchClear(){const input=document.querySelector('#product-search');input.value='';document.querySelector('#product-suggestions').hidden=true;input.focus()}
function renderCart(){const body=document.querySelector('#cart');if(!body)return;body.innerHTML=cart.length?cart.map((r,i)=>{const rate=lineDiscount(r),mrp=Number(r.product.mrp||0),price=wholesaleUnit(r.product,rate),gst=wholesaleGst(r.product,rate),incl=discountedInclusive(r.product,rate);return `<tr><td><b>${escapeHtml(r.product.name)}</b><small class="cell-sub">${rate}% off MRP</small></td><td>${currency(mrp)}</td><td><button class="quantity-link" type="button" data-qty="${i}" aria-label="Edit quantity ${r.qty}">${Number(r.qty).toLocaleString('en-IN')}</button></td><td>${currency(price)}</td><td>${currency(gst)}</td><td>${currency(incl)}</td><td class="amount">${currency(incl*r.qty)}</td><td><button class="icon-button remove-item" data-remove="${i}" aria-label="Remove item">×</button></td></tr>`}).join(''):'<tr><td colspan="8" class="cart-empty">Choose a product to start this bill.</td></tr>';const subtotal=money(cart.reduce((a,r)=>a+wholesaleUnit(r.product,lineDiscount(r))*r.qty,0)),tax=money(cart.reduce((a,r)=>a+wholesaleGst(r.product,lineDiscount(r))*r.qty,0)),total=money(cart.reduce((a,r)=>a+discountedInclusive(r.product,lineDiscount(r))*r.qty,0));document.querySelector('#subtotal').textContent=currency(subtotal);document.querySelector('#tax-total').textContent=currency(tax);document.querySelector('#grand-total').textContent=currency(total);renderEarlySavings(total);updateBillReady()}
function renderEarlySavings(total){const box=document.querySelector('#early-savings');if(!box)return;const enabled=document.querySelector('#plus-discount-enabled').checked,rate=Number(document.querySelector('#plus-discount-rate').value||0),days=Number(document.querySelector('#payment-days').value||0);box.hidden=!enabled||rate<=0||days<=0;if(box.hidden)return;const savings=money(total*rate/100),due=new Date();due.setDate(due.getDate()+days);box.textContent=`Pay by ${due.toLocaleDateString('en-IN')} to save ${currency(savings)} more (${rate}% of this invoice).`}
function updateBillReady(){const b=document.querySelector('#save-sale');if(!b)return;const paid=Number(document.querySelector('#amount-paid')?.value),discountText=document.querySelector('#customer-discount')?.value||'',discount=Number(discountText),plus=document.querySelector('#plus-discount-enabled').checked,plusRate=Number(document.querySelector('#plus-discount-rate').value||0),days=Number(document.querySelector('#payment-days').value||0),total=money(cart.reduce((a,r)=>a+discountedInclusive(r.product,lineDiscount(r))*r.qty,0));b.disabled=!document.querySelector('#bill-customer')?.value||discountText.trim()===''||!Number.isFinite(discount)||discount<0||discount>=100||!cart.length||!Number.isFinite(paid)||paid<=0||paid>total||(plus&&(!Number.isFinite(plusRate)||plusRate<=0||plusRate>=100||!Number.isInteger(days)||days<=0));renderEarlySavings(total)}
async function chooseBillAction(){const amount=Number(document.querySelector('#amount-paid').value),total=money(cart.reduce((a,r)=>a+discountedInclusive(r.product,lineDiscount(r))*r.qty,0));if(document.querySelector('#save-sale').disabled||!cart.length||!document.querySelector('#bill-customer').value||!Number.isFinite(amount)||amount<=0||amount>total){toast('Select a registered customer, enter discounts, add items, and enter payment received now.',true);return}const d=document.createElement('dialog');d.className='modal bill-choice-modal';d.innerHTML=`<section class="modal-card"><button class="modal-close" type="button" aria-label="Close">×</button><p class="eyebrow">COMPLETE WHOLESALE BILL</p><h2>How would you like to finish?</h2><p class="muted">The bill will be saved, inventory deducted, and the customer balance updated.</p><div class="bill-choice-actions"><button class="secondary" data-action="save">Save to customer account</button><button class="primary" data-action="print">Save and print invoice PDF</button></div></section>`;document.body.append(d);d.showModal();d.querySelector('.modal-close').onclick=()=>d.close();d.querySelectorAll('[data-action]').forEach(btn=>btn.onclick=async()=>{const shouldPrint=btn.dataset.action==='print';d.close();await saveSale(shouldPrint)});d.addEventListener('close',()=>d.remove())}
async function saveSale(shouldPrint=false){if(previewMode){toast('Preview only. Connect the store database to save bills.');return}const customer=document.querySelector('#bill-customer').value,discount=Number(document.querySelector('#customer-discount').value),paid=Number(document.querySelector('#amount-paid').value),plusOn=document.querySelector('#plus-discount-enabled').checked,plusRate=plusOn?Number(document.querySelector('#plus-discount-rate').value):0,days=plusOn?Number(document.querySelector('#payment-days').value):0,total=money(cart.reduce((a,r)=>a+discountedInclusive(r.product,lineDiscount(r))*r.qty,0));if(!customer||!cart.length||!Number.isFinite(discount)||discount<0||discount>=100||!Number.isFinite(paid)||paid<=0||paid>total){toast('Customer, discount, items, and payment received now are required.',true);return}const showDiscount=document.querySelector('#print-discount').checked,printWindow=shouldPrint?window.open('about:blank','_blank'):null,b=document.querySelector('#save-sale');b.disabled=true;b.textContent='Saving bill…';const savedCart=cart.map(r=>({...r}));try{const result=await db('rpc/complete_wholesale_sale',{method:'POST',body:JSON.stringify({p_customer_id:customer,p_discount_rate:discount,p_amount_paid:paid,p_extra_discount_rate:plusRate,p_payment_days:days,p_print_discount_rate:showDiscount,p_items:cart.map(r=>({product_id:r.product.id,quantity:r.qty,discount_rate:lineDiscount(r)}))})});const tx=Array.isArray(result)?result[0]:result;toast('Invoice saved. Inventory and customer ledger are up to date.');cart=[];page='invoices';await loadData();render();if(shouldPrint){if(printWindow)printWholesaleInvoice(printWindow,tx,savedCart,discount,paid,showDiscount);else toast('Invoice saved. Allow pop-ups to print or save as PDF.',true)}}catch(e){if(printWindow)printWindow.close();toast(String(e.message||e).includes('complete_wholesale_sale')?'Run updated schema.sql in Supabase to enable the revised wholesale invoice fields.':e.message,true);b.disabled=false;b.innerHTML='Complete bill <span>→</span>'}}
function printWholesaleInvoice(w,tx,rows,discount,paid,showDiscount=true){const cust=customers.find(c=>c.id===tx?.customer_id),subtotal=money(rows.reduce((a,r)=>a+wholesaleUnit(r.product,lineDiscount(r))*r.qty,0)),tax=money(rows.reduce((a,r)=>a+wholesaleGst(r.product,lineDiscount(r))*r.qty,0)),total=money(rows.reduce((a,r)=>a+discountedInclusive(r.product,lineDiscount(r))*r.qty,0)),savings=money(total*Number(tx?.extra_discount_rate||0)/100),due=tx?.discount_due_date?new Date(`${tx.discount_due_date}T00:00:00`):new Date(tx?.created_at||Date.now());if(!tx?.discount_due_date)due.setDate(due.getDate()+Number(tx?.payment_days||0));w.document.write(`<!doctype html><html><head><title>Invoice ${escapeHtml(tx?.reference||'')}</title><style>@page{size:A5 portrait;margin:9mm}*{box-sizing:border-box}body{font:8.5px Arial,sans-serif;color:#292720;margin:0}h1{font-size:15px;margin:0;color:#a94d29}header{display:flex;justify-content:space-between;border-bottom:1px solid #a94d29;padding-bottom:8px}header p{margin:3px 0}table{width:100%;border-collapse:collapse;margin-top:12px}th,td{text-align:left;border-bottom:1px solid #ddd;padding:4px 3px;font-size:7px}th{font-size:6.5px;text-transform:uppercase}td:last-child,th:last-child{text-align:right}.totals{margin:10px 0 0 auto;width:170px}.totals div{display:flex;justify-content:space-between;padding:3px}.totals .grand{font-size:10px;font-weight:bold;border-top:1px solid #333;margin-top:4px;padding-top:6px}.terms{margin-top:10px;padding:7px;background:#f6f1e8;font-size:7.5px;line-height:1.4}</style></head><body><header><div><h1>Om Sri Laxmi Traders</h1><p>Wholesale Tax Invoice</p></div><div><b>${escapeHtml(tx?.reference||'—')}</b><br>${new Date(tx?.created_at||Date.now()).toLocaleDateString('en-IN')}</div></header><p><b>Customer:</b> ${escapeHtml(cust?.name||tx?.customer_name||'')}</p><table><thead><tr><th>Item</th><th>MRP</th>${showDiscount?'<th>Discount %</th>':''}<th>Qty</th><th>Price</th><th>5% GST</th><th>Incl. Tax</th><th>Total</th></tr></thead><tbody>${rows.map(r=>{const d=lineDiscount(r),inc=discountedInclusive(r.product,d);return `<tr><td>${escapeHtml(r.product.name)}</td><td>${currency(r.product.mrp)}</td>${showDiscount?`<td>${d}%</td>`:''}<td>${Number(r.qty).toLocaleString('en-IN')}</td><td>${currency(wholesaleUnit(r.product,d))}</td><td>${currency(wholesaleGst(r.product,d))}</td><td>${currency(inc)}</td><td>${currency(inc*r.qty)}</td></tr>`}).join('')}</tbody></table><div class="totals"><div><span>Subtotal</span><b>${currency(subtotal)}</b></div><div><span>GST</span><b>${currency(tax)}</b></div><div class="grand"><span>Total</span><b>${currency(total)}</b></div><div><span>Payment received</span><b>${currency(paid)}</b></div><div><span>Balance due</span><b>${currency(total-paid)}</b></div></div>${Number(tx?.payment_days)>0&&Number(tx?.extra_discount_rate)>0?`<p class="terms">Please pay the balance by ${due.toLocaleDateString('en-IN')} (${tx.payment_days} days from bill date). Pay by then to save ${currency(savings)} more.</p>`:''}<script>window.onload=()=>window.print()<\/script></body></html>`);w.document.close()}
function dialog(title, fields, onSave){const d=document.createElement('dialog');d.className='modal';d.innerHTML=`<form method="dialog" class="modal-card" id="modal-form"><button class="modal-close" value="cancel" aria-label="Close">×</button><p class="eyebrow">${STORE.toUpperCase()}</p><h2>${title}</h2><div class="modal-fields">${fields}</div><div class="modal-actions"><button class="secondary" value="cancel">Cancel</button><button class="primary" id="modal-save" type="button">Save</button></div></form>`;document.body.append(d);d.showModal();d.querySelector('#modal-save').onclick=async()=>{if(previewMode){toast('Preview only. Connect the store database to save changes.');return}const b=d.querySelector('#modal-save');b.disabled=true;b.textContent='Saving…';try{await onSave(new FormData(d.querySelector('form')));d.close();d.remove();await loadData();renderApp();toast(`${title} saved successfully.`)}catch(e){b.disabled=false;b.textContent='Save';toast(e.message,true)}};d.addEventListener('close',()=>d.remove())}
const field=(name,label,type='text',required=false,placeholder='',extra='')=>`<label>${label}<input name="${name}" type="${type}" placeholder="${placeholder}" ${required?'required':''} ${extra}/></label>`;
function productDialog(){dialog('Add product',field('name','Product name','text',true,'e.g. Basmati rice')+`<div class="form-row">${field('stock_quantity','Opening stock (must be above zero)','number',true,'0.001','min="0.001" step="0.001"')}${field('unit','Unit','text',true,'kg, pcs, box…')}</div><div class="form-row">${field('mrp','MRP','number',true,'0','min="0.01" step="0.01"')}${field('low_stock_threshold','Low-stock warning at','number',false,'5','min="0"')}</div><div class="form-row">${field('retail_price','Retail price','number',true,'0','min="0" step="0.01"')}${field('wholesale_price','Wholesale price','number',true,'0','min="0" step="0.01"')}</div>`,async f=>{await db('products',{method:'POST',body:JSON.stringify({name:f.get('name'),stock_quantity:Number(f.get('stock_quantity')),unit:f.get('unit'),mrp:Number(f.get('mrp')),retail_price:Number(f.get('retail_price')),wholesale_price:Number(f.get('wholesale_price')),low_stock_threshold:Number(f.get('low_stock_threshold')||5)})})})}
function customerDialog(){dialog('Add customer',field('name','Customer name','text',true,'Full name')+`<div class="form-row">${field('phone','Phone number','tel',false,'Optional')}${field('email','Email','email',false,'Optional')}</div>`+field('opening_balance','Opening balance owed','number',false,'0','min="0" step="0.01"'),async f=>{const balance=Number(f.get('opening_balance')||0);const [c]=await db('customers',{method:'POST',body:JSON.stringify({name:f.get('name'),phone:f.get('phone')||null,email:f.get('email')||null,balance})});if(balance>0)await db('rpc/record_opening_balance',{method:'POST',body:JSON.stringify({p_customer_id:c.id,p_amount:balance})})})}
function paymentDialog(id){const c=customers.find(c=>c.id===id);if(!c)return;dialog(`Record payment · ${escapeHtml(c.name)}`,`<p class="muted" style="font-size:10px;margin-bottom:14px">Current balance: <b>${currency(c.balance)}</b></p>`+field('amount','Amount received','number',true,'0','min="0.01" step="0.01"')+field('notes','Note','text',false,'Optional payment note'),async f=>{await db('rpc/record_payment',{method:'POST',body:JSON.stringify({p_customer_id:id,p_amount:Number(f.get('amount')),p_notes:f.get('notes')||null})})})}
function stockDialog(id){const p=products.find(p=>p.id===id);if(!p)return;dialog(`Adjust stock · ${escapeHtml(p.name)}`,`<p class="muted" style="font-size:10px;margin-bottom:14px">Current stock: <b>${p.stock_quantity} ${escapeHtml(p.unit||'units')}</b>. Use a positive number to add stock and a negative number to remove it.</p>`+field('delta','Stock change','number',true,'e.g. 12 or -2','step="0.001"')+field('notes','Reason','text',false,'Restock, correction…'),async f=>{await db('rpc/adjust_stock',{method:'POST',body:JSON.stringify({p_product_id:id,p_delta:Number(f.get('delta')),p_notes:f.get('notes')||null})})})}
async function saveSettings(e){e.preventDefault();if(previewMode){toast('Preview only. Connect the store database to save settings.');return}const f=new FormData(e.currentTarget);try{const rows=await db('store_settings?select=id',{method:'GET'});const body={currency:f.get('currency'),tax_rate:Number(f.get('tax_rate')||0)};if(rows?.[0]) await db(`store_settings?id=eq.${rows[0].id}`,{method:'PATCH',body:JSON.stringify(body)});else await db('store_settings',{method:'POST',body:JSON.stringify(body)});settings={...settings,...body};renderApp();toast('Billing preferences saved.')}catch(err){toast(err.message,true)}}
async function initializeAuth(){if(!supabase){renderLogin();toast('Supabase connection is not configured.',true);return}const {data,error}=await supabase.auth.getSession();session=data?.session||null;if(session)await loadData();render();if(error)toast(error.message,true);}
initializeAuth();
